// A workflow execution failed (n8n Error Workflow). Describe it in the technical error contract.
const data = $input.first().json;
const execution = data.execution ?? {};
const error = execution.error ?? data.trigger?.error ?? {};
const message = String(error.message ?? error.description ?? "Unknown error").slice(0, 2000);
const node = execution.lastNodeExecuted ?? error.node?.name ?? null;

// The fingerprint groups repeats of the same problem: numbers, ids and quoted values are removed.
const normalized = message
  .replace(/\b(RFQ|QUO)-\d{8}-[A-Z0-9]{6}\b/g, "<id>")
  .replace(/<[^>@\s]+@[^>\s]+>/g, "<message-id>")
  .replace(/"[^"]*"/g, '"…"')
  .replace(/\b[0-9a-f]{16,}\b/gi, "<hash>")
  .replace(/\d+/g, "#");

return [
  {
    json: {
      source: "execution_error",
      event_type: "execution_failed",
      workflow_id: data.workflow?.id ?? null,
      workflow_name: data.workflow?.name ?? null,
      execution_id: execution.id ?? null,
      execution_url: execution.url ?? null,
      node,
      message,
      reference: message.match(/\b(RFQ|QUO)-\d{8}-[A-Z0-9]{6}\b/)?.[0] ?? null,
      fingerprint: `${data.workflow?.id ?? "?"}|${node ?? "?"}|${normalized}`.slice(0, 1000),
    },
  },
];

// A technical failure that the workflows handle themselves (so the execution succeeds) but an
// administrator must know about: RFQ FAILED after retries, LLM API failure, customer delivery failure.
// Contract: { operation: "ops_event", payload: { event_type, message, reference?, workflow_name? } }
const command = $input.first().json;
if (command.operation !== "ops_event") {
  throw new Error(`Unknown ops operation: ${command.operation}`);
}
const payload = command.payload ?? {};
const eventType = String(payload.event_type ?? "unknown");
const message = String(payload.message ?? "").slice(0, 2000) || "(no message)";
const normalized = message
  .replace(/\b(RFQ|QUO)-\d{8}-[A-Z0-9]{6}\b/g, "<id>")
  .replace(/\b[0-9a-f]{16,}\b/gi, "<hash>")
  .replace(/\d+/g, "#");

return [
  {
    json: {
      source: "ops_event",
      event_type: eventType,
      workflow_id: null,
      workflow_name: payload.workflow_name ?? null,
      execution_id: null,
      execution_url: null,
      node: null,
      message,
      reference: payload.reference ? String(payload.reference) : null,
      fingerprint: `ops|${eventType}|${normalized}`.slice(0, 1000),
    },
  },
];

// Email the administrator. If the database itself failed, the error cannot be recorded and the
// recipients are unknown: the execution fails loudly and GET /webhook/health reports the outage.
const recorded = $input.first().json;
const event = $('Technical Error').first().json;

if (recorded.error) {
  throw new Error(`Could not record technical error (${event.event_type}: ${event.message}): ${recorded.error.message ?? recorded.error}`);
}
if (!recorded.should_alert) {
  return [];
}

const settings = recorded.settings ?? {};
const recipients = settings.alert_recipients;
if (!Array.isArray(recipients) || recipients.length === 0) {
  throw new Error("app_settings.alert_recipients must list at least one address.");
}

// Administrator-facing technical texts (not client communication templates).
const TEXTS = {
  pl: {
    subject: "[RFQ Automation] Problem techniczny: {title}",
    intro: "System RFQ Automation zgłosił problem techniczny.",
    type: "Typ", workflow: "Workflow", node: "Node", message: "Komunikat", reference: "Dotyczy",
    time: "Czas", execution: "Wykonanie w n8n", occurrences: "Wystąpienia tego problemu w ostatnich 24 h",
    cooldown: "Kolejne wystąpienia tego samego problemu są zapisywane w tabeli technical_errors; następny mail najwcześniej za {minutes} min.",
  },
  en: {
    subject: "[RFQ Automation] Technical problem: {title}",
    intro: "RFQ Automation reported a technical problem.",
    type: "Type", workflow: "Workflow", node: "Node", message: "Message", reference: "Reference",
    time: "Time", execution: "n8n execution", occurrences: "Occurrences of this problem in the last 24 h",
    cooldown: "Further occurrences of the same problem are recorded in technical_errors; the next email is sent after {minutes} min at the earliest.",
  },
};
const t = TEXTS[settings.language] ?? TEXTS.en;
const fill = (template, values) => template.replace(/\{(\w+)\}/g, (m, k) => (k in values ? String(values[k]) : m));
const title = event.workflow_name ? `${event.workflow_name}${event.node ? ` / ${event.node}` : ""}` : event.event_type;

const lines = [
  t.intro,
  "",
  `${t.type}: ${event.event_type}`,
  ...(event.workflow_name ? [`${t.workflow}: ${event.workflow_name}`] : []),
  ...(event.node ? [`${t.node}: ${event.node}`] : []),
  `${t.message}: ${event.message}`,
  ...(event.reference ? [`${t.reference}: ${event.reference}`] : []),
  `${t.time}: ${recorded.occurred_at}`,
  ...(event.execution_url ? [`${t.execution}: ${event.execution_url}`] : []),
  `${t.occurrences}: ${recorded.occurrences_24h}`,
  "",
  fill(t.cooldown, { minutes: recorded.cooldown_minutes }),
];

return [
  {
    json: {
      technical_error_id: recorded.technical_error_id,
      from: settings.email_from,
      to: recipients.join(", "),
      subject: fill(t.subject, { title }).slice(0, 200),
      text: lines.join("\n"),
    },
  },
];

// Health for external monitoring: 503 only for infrastructure problems (database unreachable,
// recovery schedules not running). Business counts are informational and never change the status.
const health = $input.first().json;

if (health.error || !health.checked_at) {
  return [{
    json: {
      http_status: 503,
      // Public endpoint: no error details (they would expose internals); see the n8n execution log.
      body: { status: "down", checks: { database: "unreachable" } },
    },
  }];
}

const now = new Date(health.checked_at).getTime();
const staleMs = Number(health.stale_minutes) * 60000;
// Only the schedules of installed workflows (app_settings.health_expected_heartbeats).
const expected = Array.isArray(health.expected_heartbeats) && health.expected_heartbeats.length ? health.expected_heartbeats : ["core_recovery"];
const heartbeats = {};
for (const name of expected) {
  const lastSeen = health.heartbeats?.[name];
  const ageSeconds = lastSeen ? Math.round((now - new Date(lastSeen).getTime()) / 1000) : null;
  heartbeats[name] = {
    last_seen_at: lastSeen ?? null,
    age_seconds: ageSeconds,
    status: ageSeconds !== null && ageSeconds * 1000 <= staleMs ? "ok" : "stale",
  };
}
const healthy = Object.values(heartbeats).every(h => h.status === "ok");

return [{
  json: {
    http_status: healthy ? 200 : 503,
    body: {
      status: healthy ? "ok" : "degraded",
      checked_at: health.checked_at,
      checks: { database: "ok", heartbeats },
      attention: {
        technical_errors_last_hour: Number(health.technical_errors_1h),
        rfqs_failed_last_24h: Number(health.rfqs_failed_24h),
        quotes_send_uncertain: Number(health.quotes_send_uncertain),
        inbound_messages_failed: Number(health.inbound_messages_failed),
        open_review_tasks: Number(health.open_review_tasks),
        quotes_pending_approval: Number(health.quotes_pending_approval),
      },
    },
  },
}];
